(c, v) = ([[0] * 201 for i in range(201)], [])
n = int(input())
for i in range(n * (n - 1) // 2):
	a = list(map(int, input().split()))[1:]
	for x in a:
		for y in a:
			c[x][y] += 1
for (i, ci) in enumerate(c):
	if ci[i]:
		a = [j for (j, cij) in enumerate(ci) if cij == n - 1]
		v.append(a)
		for x in a:
			c[x][x] = 0
if len(v) == 1:
	v.append([v[0].pop()])
for vi in v:
	print(len(vi), *vi)
